/**
 * The offline material one party holds when the online phase starts, whichever way it was produced:
 * dealt by a TRUSTED DEALER over the mesh (`protocol.ts` `runDealer`) or generated by the parties themselves
 * from oblivious transfer with NO dealer (`offline-net.ts`).
 */

import type { AW, PA } from './pa';
import type { Disclosure } from './forensics';

/** Number of sharings per delivered triple: a, b, c, then (a-hat, c-hat) for each sacrifice partner. */
export const sharingsPerTriple = (partners: number): number => 3 + 2 * partners;

export interface Prep {
  /** Where this material came from. A `trusted-dealer` knows every share and key. */
  mode: 'trusted-dealer' | 'no-dealer';
  /** Whether the shares carry pairwise tags (identifiable abort). Only the trusted-dealer mode provides them. */
  tagged: boolean;
  /** My pairwise verification key Δ (0n when untagged). */
  delta: bigint;
  /** My share of each global MAC key, pairwise-authenticated. */
  alpha: PA[];
  /** Triples with their sacrifice partners: `triples[t] = [a, b, c, a-hat_1, c-hat_1, ...]` (partners share b). */
  triples: AW[][];
  /**
   * trusted-dealer: the authenticated random MASKS r for each (owner, chain), `inputs[owner*C + c]`; the owner
   * broadcasts x - r. no-dealer: the authenticated INPUT bits themselves, same indexing.
   */
  inputs: AW[];
  /** My own plaintext side of `inputs`: the masks r (trusted-dealer) or my input bits (no-dealer), one per chain. */
  myPlain: bigint[];
  /** no-dealer only: an authenticated random mask for the input-consistency check. */
  checkMask?: AW;
  /** no-dealer only: the OT transcript of the triple products, for attributing a failed sacrifice (`forensics.ts`). */
  forensics?: {
    gadget: bigint[];
    /** Choice bits per product item (the encoded width). */
    rows: number;
    /** Product slots per triple: the product and one per sacrifice partner. */
    slots: number;
    /** My disclosure for triple `t` (the triple is discarded when this is used). */
    disclose: (t: number) => Disclosure;
  };
}
